-- =====================================================================
--  SIARGAO PIXEL LIFE: ISLAND OF HOPE
--  "Play, Protect, and Rebuild Our Island."
--  MySQL 8 schema + seed data. Generated by backend/scripts/generate-sql.js
--  Import with MySQL Workbench (File > Open SQL Script > Execute All)
-- =====================================================================

CREATE DATABASE IF NOT EXISTS siargao_pixel_life
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE siargao_pixel_life;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS spot_visits, quiz_attempts, quiz_questions, quizzes, trash_pickups,
  activity_records, surfing_records, rewards, marine_conservation_records, cleanliness_records,
  mission_progress, missions, activities, npcs, shop_items, player_profiles, tourist_spots, users;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------
CREATE TABLE users (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  username       VARCHAR(32)  NOT NULL,
  email          VARCHAR(255) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  role           ENUM('local_resident','tourist') NOT NULL,
  account_type   ENUM('player','admin') NOT NULL DEFAULT 'player',
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at  TIMESTAMP NULL DEFAULT NULL,
  UNIQUE KEY uq_users_username (username),
  UNIQUE KEY uq_users_email (email),
  KEY idx_users_role (role)
) ENGINE=InnoDB;

CREATE TABLE tourist_spots (
  id                      INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  spot_key                VARCHAR(40)  NOT NULL,
  name                    VARCHAR(120) NOT NULL,
  municipality            VARCHAR(120) NOT NULL DEFAULT '',
  description             TEXT NOT NULL,
  location_type           VARCHAR(40)  NOT NULL,
  cleanliness_percentage  DECIMAL(5,2) NOT NULL DEFAULT 70.00,
  environment_data        JSON NOT NULL,
  last_decay_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  is_active               TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_spots_key (spot_key),
  CONSTRAINT chk_spot_clean CHECK (cleanliness_percentage BETWEEN 0 AND 100)
) ENGINE=InnoDB;

CREATE TABLE player_profiles (
  id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id           INT UNSIGNED NOT NULL,
  level             INT UNSIGNED NOT NULL DEFAULT 1,
  experience        INT UNSIGNED NOT NULL DEFAULT 0,
  coins             INT UNSIGNED NOT NULL DEFAULT 300,
  surfing_skill     INT UNSIGNED NOT NULL DEFAULT 0,
  eco_points        INT UNSIGNED NOT NULL DEFAULT 0,
  appearance        JSON NULL,
  current_spot_id   INT UNSIGNED NULL,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_profile_user (user_id),
  CONSTRAINT fk_profile_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_profile_spot FOREIGN KEY (current_spot_id) REFERENCES tourist_spots(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- World content
-- ---------------------------------------------------------------------
CREATE TABLE npcs (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  npc_key          VARCHAR(40) NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  name             VARCHAR(80) NOT NULL,
  npc_role         VARCHAR(80) NOT NULL,
  dialogue         JSON NOT NULL,
  info             TEXT NULL,
  UNIQUE KEY uq_npc_key (npc_key),
  KEY idx_npc_spot (tourist_spot_id),
  CONSTRAINT fk_npc_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE activities (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  activity_key     VARCHAR(60) NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  activity_name    VARCHAR(120) NOT NULL,
  activity_type    ENUM('cleanup','maintenance','surf','explore','kayak','community','quiz') NOT NULL,
  description      TEXT NOT NULL,
  config           JSON NULL,
  is_active        TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_activity_key (activity_key),
  KEY idx_activity_spot (tourist_spot_id),
  CONSTRAINT fk_activity_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE missions (
  id                 INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  mission_key        VARCHAR(60) NOT NULL,
  tourist_spot_id    INT UNSIGNED NOT NULL,
  title              VARCHAR(160) NOT NULL,
  description        TEXT NOT NULL,
  mission_category   ENUM('environmental_protection','beach_cleanup','marine_conservation','surfing',
                          'responsible_tourism','community_service','local_culture','exploration') NOT NULL,
  difficulty         ENUM('easy','medium','hard') NOT NULL DEFAULT 'easy',
  recommended_role   ENUM('local_resident','tourist','both') NOT NULL DEFAULT 'both',
  objectives         JSON NOT NULL,
  reward_xp          INT UNSIGNED NOT NULL DEFAULT 0,
  reward_coins       INT UNSIGNED NOT NULL DEFAULT 0,
  reward_badge       VARCHAR(120) NULL,
  is_repeatable      TINYINT(1) NOT NULL DEFAULT 0,
  cooldown_hours     INT UNSIGNED NOT NULL DEFAULT 6,
  is_active          TINYINT(1) NOT NULL DEFAULT 1,
  created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_mission_key (mission_key),
  KEY idx_mission_spot (tourist_spot_id),
  KEY idx_mission_category (mission_category),
  CONSTRAINT fk_mission_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE quizzes (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  quiz_key         VARCHAR(60) NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  title            VARCHAR(160) NOT NULL,
  category         ENUM('marine','tourism','environment','community') NOT NULL,
  pass_ratio       DECIMAL(3,2) NOT NULL DEFAULT 0.60,
  UNIQUE KEY uq_quiz_key (quiz_key),
  CONSTRAINT fk_quiz_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE quiz_questions (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  quiz_id        INT UNSIGNED NOT NULL,
  question       TEXT NOT NULL,
  options        JSON NOT NULL,
  correct_index  TINYINT UNSIGNED NOT NULL,
  explanation    TEXT NULL,
  sort_order     INT NOT NULL DEFAULT 0,
  KEY idx_question_quiz (quiz_id),
  CONSTRAINT fk_question_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE shop_items (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  item_key         VARCHAR(60) NOT NULL,
  name             VARCHAR(120) NOT NULL,
  item_type        ENUM('surfboard','cosmetic','local_product') NOT NULL,
  price            INT UNSIGNED NOT NULL DEFAULT 0,
  tourist_spot_id  INT UNSIGNED NULL,
  description      TEXT NOT NULL,
  data             JSON NULL,
  UNIQUE KEY uq_item_key (item_key),
  CONSTRAINT fk_item_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- Player progress & records
-- ---------------------------------------------------------------------
CREATE TABLE mission_progress (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id       INT UNSIGNED NOT NULL,
  mission_id    INT UNSIGNED NOT NULL,
  progress      JSON NOT NULL,
  status        ENUM('active','completed','abandoned') NOT NULL DEFAULT 'active',
  started_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at  TIMESTAMP NULL DEFAULT NULL,
  KEY idx_mp_user_status (user_id, status),
  KEY idx_mp_mission (mission_id),
  CONSTRAINT fk_mp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_mp_mission FOREIGN KEY (mission_id) REFERENCES missions(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE activity_records (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id       INT UNSIGNED NOT NULL,
  activity_id   INT UNSIGNED NOT NULL,
  result        JSON NULL,
  completed_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_ar_user (user_id, completed_at),
  KEY idx_ar_activity (activity_id),
  CONSTRAINT fk_ar_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_ar_activity FOREIGN KEY (activity_id) REFERENCES activities(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE trash_pickups (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id          INT UNSIGNED NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  trash_index      SMALLINT UNSIGNED NOT NULL,
  picked_at        TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  KEY idx_tp_user_spot_time (user_id, tourist_spot_id, picked_at),
  CONSTRAINT fk_tp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_tp_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cleanliness_records (
  id                   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id              INT UNSIGNED NOT NULL,
  tourist_spot_id      INT UNSIGNED NOT NULL,
  mission_id           INT UNSIGNED NULL,
  source               ENUM('pickup','mission','maintenance') NOT NULL DEFAULT 'pickup',
  cleanup_count        INT UNSIGNED NOT NULL DEFAULT 0,
  contribution_points  INT UNSIGNED NOT NULL DEFAULT 0,
  created_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_cr_spot (tourist_spot_id, created_at),
  KEY idx_cr_user (user_id),
  CONSTRAINT fk_cr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_cr_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE,
  CONSTRAINT fk_cr_mission FOREIGN KEY (mission_id) REFERENCES missions(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE marine_conservation_records (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id          INT UNSIGNED NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  activity_type    VARCHAR(60) NOT NULL,
  details          VARCHAR(255) NULL,
  completed_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_mcr_spot (tourist_spot_id),
  KEY idx_mcr_user (user_id),
  CONSTRAINT fk_mcr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_mcr_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE rewards (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id      INT UNSIGNED NOT NULL,
  reward_key   VARCHAR(80) NOT NULL,
  reward_name  VARCHAR(160) NOT NULL,
  reward_type  ENUM('badge','achievement','certificate','surfboard','cosmetic','local_product') NOT NULL,
  earned_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_rewards_user (user_id, reward_type),
  CONSTRAINT fk_rewards_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE surfing_records (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id          INT UNSIGNED NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  challenge        ENUM('tutorial','beginner','intermediate','free') NOT NULL DEFAULT 'free',
  board_key        VARCHAR(60) NOT NULL,
  score            INT UNSIGNED NOT NULL,
  duration         DECIMAL(6,2) NOT NULL,
  waves            TINYINT UNSIGNED NOT NULL DEFAULT 1,
  carves           SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  passed           TINYINT(1) NOT NULL DEFAULT 0,
  completed_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_surf_score (tourist_spot_id, score),
  KEY idx_surf_user (user_id),
  CONSTRAINT fk_surf_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_surf_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE quiz_attempts (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id     INT UNSIGNED NOT NULL,
  quiz_id     INT UNSIGNED NOT NULL,
  score       TINYINT UNSIGNED NOT NULL,
  total       TINYINT UNSIGNED NOT NULL,
  passed      TINYINT(1) NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_qa_user (user_id),
  CONSTRAINT fk_qa_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_qa_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE spot_visits (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id          INT UNSIGNED NOT NULL,
  tourist_spot_id  INT UNSIGNED NOT NULL,
  visited_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_visit_user (user_id, tourist_spot_id),
  CONSTRAINT fk_visit_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_visit_spot FOREIGN KEY (tourist_spot_id) REFERENCES tourist_spots(id) ON DELETE CASCADE
) ENGINE=InnoDB;


-- =====================================================================
-- Seed data
-- =====================================================================

INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('cloud9', 'Cloud 9', 'General Luna', 'The surfing capital of the Philippines. Its famous wooden boardwalk leads to a viewing tower above a thick right-hand reef break.', 'surf_beach', 65, '{"theme":"cloud9","trashCount":24,"surf":true,"mapPos":{"x":63,"y":66},"facts":["Cloud 9 is a reef break: waves break over living coral, so surfers must never stand on the reef.","The boardwalk lets visitors reach the lineup without trampling the reef flat.","Plastic left on the beach is carried into the reef by the tide within hours."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('magpupungko', 'Magpupungko Rock Pools', 'Pilar', 'Giant rock formations and natural tidal pools that appear at low tide, full of tiny sea creatures.', 'tidal_pools', 72, '{"theme":"magpupungko","trashCount":20,"surf":false,"mapPos":{"x":72,"y":40},"facts":["The tidal pools are only safe to swim in at low tide; always check the tide schedule.","Sea urchins, small fish and crabs live in the pools — look, but never take them home.","Sunscreen with oxybenzone harms tiny pool organisms. Use reef-safe sunscreen."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('sugba', 'Sugba Lagoon', 'Del Carmen', 'A calm emerald lagoon surrounded by limestone cliffs and the largest mangrove forest in Mindanao.', 'lagoon', 80, '{"theme":"sugba","trashCount":18,"surf":false,"mapPos":{"x":30,"y":52},"facts":["Del Carmen protects one of the largest contiguous mangrove forests in the Philippines.","Mangroves are nurseries for fish and protect villages from storm surges.","Single-use plastic is discouraged at the lagoon — bring a reusable water bottle."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('naked', 'Naked Island', 'General Luna', 'A bare white sandbar with no trees or buildings — just sand, sun and a 360° view of turquoise water.', 'sandbar', 70, '{"theme":"naked","trashCount":16,"surf":false,"mapPos":{"x":72,"y":76},"facts":["Naked Island has no bins: everything you bring, you must bring back.","Sandbars change shape with tides and storms — they are fragile, living landforms.","Floating plastic washes up here from the open sea, so cleanups help the whole coast."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('guyam', 'Guyam Island', 'General Luna', 'A tiny, round islet crowned with coconut trees — the postcard of island hopping in Siargao.', 'islet', 78, '{"theme":"guyam","trashCount":16,"surf":false,"mapPos":{"x":66,"y":80},"facts":["Guyam is cared for by caretakers from the local barangay; the small entrance fee funds cleanups.","Never carve names into coconut trees — the wounds let pests and disease in.","Coconut crabs and nesting birds depend on undisturbed islet vegetation."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('daku', 'Daku Island', 'General Luna', 'The largest of the three island-hopping islands, home to a fishing community and long white beaches.', 'village_island', 68, '{"theme":"daku","trashCount":22,"surf":false,"mapPos":{"x":58,"y":84},"facts":["Daku means \\"big\\" in Surigaonon. Families here live from fishing and coconut farming.","Buying grilled fish or crafts from locals keeps tourism money inside the community.","Fishers practice sustainable catch sizes so reef fish can keep reproducing."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('pacifico', 'Pacifico Beach', 'San Isidro', 'A long, quiet beach in the north with consistent waves and a relaxed, local vibe.', 'surf_beach', 75, '{"theme":"pacifico","trashCount":20,"surf":true,"mapPos":{"x":80,"y":22},"facts":["Pacifico faces the open Pacific, so swells arrive here first.","Sea turtles feed in the seagrass beds offshore; give them at least 3 meters of space.","Fishing lines and nets left on the beach can entangle turtles and seabirds."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('sohoton', 'Sohoton Cove', 'Socorro, Bucas Grande', 'A hidden cove reached through a low cave entrance, known for its stingless jellyfish and crystal waters.', 'cove', 85, '{"theme":"sohoton","trashCount":14,"surf":false,"mapPos":{"x":20,"y":18},"facts":["Sohoton is a protected area: only registered boats and guides may enter.","Stingless jellyfish are delicate — touching or lifting them out of the water can kill them.","Boat engines are switched off inside the cove to protect the calm, clear water."]}');
INSERT INTO tourist_spots (spot_key, name, municipality, description, location_type, cleanliness_percentage, environment_data) VALUES ('taktak', 'Taktak Falls', 'Santa Monica', 'A multi-tiered waterfall hidden in the forest, with a cool, refreshing swimming basin.', 'waterfall', 74, '{"theme":"taktak","trashCount":18,"surf":false,"mapPos":{"x":50,"y":12},"facts":["River water from Taktak flows down to the mangroves and reefs — litter here ends up in the sea.","Soap and shampoo pollute fresh water: never bathe with them in natural pools.","Stay on marked trails to avoid erosion of the forest floor."]}');

INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('kuya_jun', (SELECT id FROM tourist_spots WHERE spot_key = 'cloud9'), 'Kuya Jun', 'Surf Instructor', '["Welcome to Cloud 9, the wave that made Siargao famous!","Before you surf: respect the lineup, never drop in on another surfer, and never stand on the reef.","Pick a board at the rental shop and paddle out when you are ready. I will guide you!"]', 'Surf etiquette: the surfer closest to the peak has the right of way. Wait your turn and smile!');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('ate_marites', (SELECT id FROM tourist_spots WHERE spot_key = 'cloud9'), 'Ate Marites', 'Environmental Volunteer', '["Every morning the tide brings plastic back to the beach.","If everyone picks up just a few pieces, Cloud 9 stays beautiful for everyone.","Would you help us? Collect the trash along the shore and put it in the eco bins."]', 'A plastic bottle can take 450 years to break down — and it never truly disappears, it becomes microplastic.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('mang_ramon', (SELECT id FROM tourist_spots WHERE spot_key = 'cloud9'), 'Mang Ramon', 'Boardwalk Caretaker', '["This boardwalk takes a beating from the salt and the storms.","Some planks are loose. A safe boardwalk keeps visitors off the fragile reef flat.","Find the marked planks and press E to fix them."]', 'Boardwalks protect coastal habitats by guiding foot traffic away from reef flats and dunes.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('lola_pacing', (SELECT id FROM tourist_spots WHERE spot_key = 'magpupungko'), 'Lola Pacing', 'Local Resident', '["I have watched these pools since I was a little girl.","At low tide they fill with clear water and little fish. At high tide the waves crash over the rocks.","Please, do not take shells or creatures home. They belong here."]', 'Tidal pool creatures survive extreme heat and salt changes, but not being moved or handled.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('tour_guide_ben', (SELECT id FROM tourist_spots WHERE spot_key = 'magpupungko'), 'Guide Ben', 'Tourist Guide', '["Hello! I am a registered tour guide here in Pilar.","Read the info boards around the rocks to learn how the pools formed.","Then take my quick quiz — I will give you a certificate for responsible visitors!"]', 'Hiring registered local guides supports families and keeps visitors safe from the tide.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('kapitan_doming', (SELECT id FROM tourist_spots WHERE spot_key = 'sugba'), 'Kapitan Doming', 'Barangay Community Leader', '["Maayong adlaw! Welcome to Sugba Lagoon in Del Carmen.","Our mangroves feed the fish that feed our families.","Take a kayak, explore quietly, and help us fish out any floating litter."]', 'Del Carmen replanted thousands of mangrove seedlings after Typhoon Odette in 2021.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('kayak_nene', (SELECT id FROM tourist_spots WHERE spot_key = 'sugba'), 'Nene', 'Kayak Rental', '["Want to paddle? Kayaks are quiet and do not pollute the water.","Follow the yellow buoys around the lagoon. Use A and D to paddle left and right!"]', 'Paddling instead of motor boats keeps lagoon water clear and quiet for wildlife.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('bangkero_toto', (SELECT id FROM tourist_spots WHERE spot_key = 'naked'), 'Toto', 'Boatman (Bangkero)', '["This is Naked Island — no trees, no shade, just sand and sea!","There are no trash bins here, so whatever we bring, we take back on the boat.","Help me pick up what the waves left on the sandbar."]', 'Leave No Trace: plan ahead, carry out what you carry in, and leave what you find.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('caretaker_lito', (SELECT id FROM tourist_spots WHERE spot_key = 'guyam'), 'Lito', 'Island Caretaker', '["I look after Guyam every day.","Visitors love the coconut trees, but some carve their names into them. It hurts the trees.","Help me keep the shore clean and learn about the reef around the islet."]', 'Seagrass and coral around Guyam shelter juvenile fish that later grow up on the open reef.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('mang_tonyo', (SELECT id FROM tourist_spots WHERE spot_key = 'daku'), 'Mang Tonyo', 'Local Fisherman', '["My family has fished these waters for generations.","Plastic nets and bottles end up in my catch more and more.","If you want to help, clean the village shore and buy local — it keeps our community strong."]', 'Ghost nets — lost fishing nets — keep catching fish and turtles for years after they are lost.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('aling_nena', (SELECT id FROM tourist_spots WHERE spot_key = 'daku'), 'Aling Nena', 'Local Shop Owner', '["Fresh grilled fish, buko juice, woven bags made by our neighbors!","When you buy here, the money stays with the families of Daku."]', 'Community-based tourism shares the benefits of tourism directly with local families.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('surfer_aya', (SELECT id FROM tourist_spots WHERE spot_key = 'pacifico'), 'Aya', 'Local Surfer', '["Pacifico is quieter than Cloud 9 — perfect for practice.","Turtles feed just past the break. Never chase or touch them.","Grab a board and try the challenge when you are ready!"]', 'Keep at least 3 meters from sea turtles and never block their path to the surface.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('volunteer_carlo', (SELECT id FROM tourist_spots WHERE spot_key = 'pacifico'), 'Carlo', 'Marine Volunteer', '["We run beach cleanups here every weekend.","Fishing line and plastic straws are the worst — turtles mistake them for food."]', 'Sea turtles mistake floating plastic bags for jellyfish, one of their favorite foods.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('ranger_ines', (SELECT id FROM tourist_spots WHERE spot_key = 'sohoton'), 'Ranger Ines', 'Protected Area Ranger', '["Welcome to Sohoton Cove, part of a protected landscape.","You may swim with the stingless jellyfish, but never touch, squeeze or lift them.","Follow the rules on the boards and you can enjoy this place responsibly."]', 'Protected areas limit the number of visitors per day so the ecosystem can recover.');
INSERT INTO npcs (npc_key, tourist_spot_id, name, npc_role, dialogue, info) VALUES ('guide_rico', (SELECT id FROM tourist_spots WHERE spot_key = 'taktak'), 'Rico', 'Trail Guide', '["Taktak means \\"falling water\\" — listen to it!","This river feeds the mangroves and the sea, so keep it clean.","Please no soap or shampoo in the pool, and take your snacks wrappers home."]', 'Freshwater ecosystems connect forests to reefs — pollution travels downstream.');

