INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('marine_basics', (SELECT id FROM tourist_spots WHERE spot_key = 'cloud9'), 'Marine Protection Basics', 'marine');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'marine_basics'), 'What happens to most plastic left on the beach?', '["It disappears in a few days","The tide carries it into the sea","Crabs eat it safely","It turns into sand"]', 1, 'Tides and wind carry beach litter into the ocean, where it harms reefs and animals.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'marine_basics'), 'Why should surfers never stand on the reef?', '["It is slippery","Coral is a living animal that breaks easily","It is against surf rules only","There is no reason"]', 1, 'Coral polyps are living animals. One step can destroy decades of growth.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'marine_basics'), 'How long can a plastic bottle last in the ocean?', '["1 year","10 years","About 450 years","1 month"]', 2, 'Plastic bottles break into microplastics over hundreds of years but never truly disappear.', 2);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'marine_basics'), 'What is the best way to help marine life as a visitor?', '["Feed the fish bread","Take shells as souvenirs","Bring reusable bottles and carry your trash out","Touch coral to feel it"]', 2, 'Reducing and carrying out waste is the simplest, most powerful action.', 3);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'marine_basics'), 'Which sunscreen is better for reefs?', '["Any spray sunscreen","Reef-safe mineral sunscreen","Cooking oil","No difference"]', 1, 'Mineral (zinc/titanium) sunscreens without oxybenzone are less harmful to coral.', 4);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('tidal_pools', (SELECT id FROM tourist_spots WHERE spot_key = 'magpupungko'), 'Tidal Pool Explorer', 'marine');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'tidal_pools'), 'When are the Magpupungko pools safe to swim in?', '["At high tide","At low tide","During storms","At night"]', 1, 'At high tide waves crash over the rocks. Always check the tide schedule.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'tidal_pools'), 'You find a beautiful shell with a creature inside. What do you do?', '["Take it home","Leave it where it is","Sell it","Give it to a friend"]', 1, 'Shells are homes. Removing them disrupts the tidal pool ecosystem.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'tidal_pools'), 'Why hire a registered local guide?', '["It is cheaper","It supports local families and keeps you safe","Guides carry your bags","It is not needed"]', 1, 'Local guides know the tides and share tourism income with the community.', 2);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'tidal_pools'), 'Where should your snack wrapper go?', '["In a rock crack","In your bag until you find a bin","In the pool","Bury it in sand"]', 1, 'Carry your trash until you find a proper bin — never hide it in nature.', 3);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('water_conservation', (SELECT id FROM tourist_spots WHERE spot_key = 'sugba'), 'Lagoon & Mangrove Conservation', 'marine');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'water_conservation'), 'Why are mangroves important?', '["They block the view","They are fish nurseries and protect against storm surge","They are only decorative","They make water salty"]', 1, 'Mangrove roots shelter baby fish and absorb wave energy during storms.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'water_conservation'), 'Which is the most eco-friendly way to explore Sugba Lagoon?', '["Jet ski","Kayak or paddleboard","Speedboat laps","Swimming with soap"]', 1, 'Paddle-powered craft create no fuel pollution or noise.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'water_conservation'), 'What should you bring to reduce plastic waste?', '["Many plastic bottles","A reusable water bottle","Styrofoam boxes","Plastic straws"]', 1, 'Reusable bottles avoid dozens of single-use plastics per trip.', 2);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'water_conservation'), 'What should you do if you see floating litter in the lagoon?', '["Ignore it","Push it away","Safely collect it and bring it to shore","Sink it"]', 2, 'Collected litter can be recycled or disposed of properly on land.', 3);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('responsible_tourism', (SELECT id FROM tourist_spots WHERE spot_key = 'guyam'), 'Responsible Tourism Challenge', 'tourism');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'responsible_tourism'), 'You want a souvenir from Guyam Island. What is best?', '["Carve your name in a coconut tree","Take sand and coral","Take photos and buy local crafts","Pick flowers"]', 2, '"Take only pictures, leave only footprints" — and support local artisans.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'responsible_tourism'), 'What does the small environmental fee at islands pay for?', '["Nothing","Cleanups and caretakers","Only souvenirs","Boat fuel only"]', 1, 'Environmental fees fund caretakers, cleanups and conservation programs.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'responsible_tourism'), 'How should you treat local residents and their culture?', '["Ignore local rules","Respect customs and ask before taking photos","Be loud everywhere","Bargain aggressively"]', 1, 'Respect makes tourism welcome and sustainable for everyone.', 2);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'responsible_tourism'), 'Who is responsible for keeping Siargao clean?', '["Only residents","Only the government","Only tourists","Everyone"]', 3, 'Siargao is everyone''s responsibility — residents and visitors alike.', 3);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('turtle_safety', (SELECT id FROM tourist_spots WHERE spot_key = 'pacifico'), 'Sea Turtle Safety', 'marine');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'turtle_safety'), 'How close should you get to a sea turtle in the water?', '["Touch it gently","At least 3 meters away","Ride on it","Hold its shell"]', 1, 'Keeping distance prevents stress and lets turtles surface to breathe.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'turtle_safety'), 'Why are plastic bags dangerous to turtles?', '["They are noisy","Turtles mistake them for jellyfish","They are too heavy","They are not dangerous"]', 1, 'Swallowed plastic blocks a turtle''s stomach and can kill it.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'turtle_safety'), 'You find old fishing line on the beach. What do you do?', '["Leave it","Throw it into the sea","Collect it and dispose of it properly","Burn it on the sand"]', 2, 'Fishing line entangles turtles and birds; collecting it saves lives.', 2);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('protected_cove', (SELECT id FROM tourist_spots WHERE spot_key = 'sohoton'), 'Protected Area Rules', 'marine');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'protected_cove'), 'How should you behave around stingless jellyfish?', '["Squeeze them","Lift them for photos","Observe without touching","Collect them in a bottle"]', 2, 'Their bodies are fragile; lifting them out of the water can kill them.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'protected_cove'), 'Why are boat engines turned off inside the cove?', '["To save money","To protect the calm, clean water and wildlife","Engines are broken","No reason"]', 1, 'Engines add noise, oil and stir up sediment in a delicate cove.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'protected_cove'), 'Why do protected areas limit visitor numbers?', '["To be exclusive","So ecosystems can recover","To raise prices","They do not"]', 1, 'Carrying capacity limits keep the environment healthy long-term.', 2);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('freshwater', (SELECT id FROM tourist_spots WHERE spot_key = 'taktak'), 'Rivers to Reefs', 'environment');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'freshwater'), 'Where does litter dropped at Taktak Falls eventually go?', '["It stays in the forest","Down the river to the mangroves and sea","Into the sky","Nowhere"]', 1, 'Rivers carry litter from mountains to mangroves and coral reefs.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'freshwater'), 'Can you use shampoo in the waterfall pool?', '["Yes, any time","Only a little","No — soaps pollute freshwater","Only biodegradable glitter"]', 2, 'Soaps and shampoos harm fish and plants in the pool and downstream.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'freshwater'), 'Why stay on marked trails?', '["To avoid erosion and protect plants","Trails are faster","No reason","To find trash"]', 0, 'Trampling off-trail damages roots and causes erosion into the river.', 2);
INSERT INTO quizzes (quiz_key, tourist_spot_id, title, category) VALUES ('community_care', (SELECT id FROM tourist_spots WHERE spot_key = 'daku'), 'Community & Local Business', 'community');
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'community_care'), 'How does buying from local stores help Daku Island?', '["It does not","Money stays with local families","It raises pollution","It only helps big hotels"]', 1, 'Local purchases directly support families and community projects.', 0);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'community_care'), 'What is a "ghost net"?', '["A haunted net","A lost fishing net that keeps catching animals","A net for catching ghosts","A volleyball net"]', 1, 'Lost nets keep trapping fish, turtles and dolphins for years.', 1);
INSERT INTO quiz_questions (quiz_id, question, options, correct_index, explanation, sort_order) VALUES ((SELECT id FROM quizzes WHERE quiz_key = 'community_care'), 'What is the best thing to do with plastic at a community cleanup?', '["Burn it","Bury it","Sort it for recycling and proper disposal","Throw it at sea"]', 2, 'Burning plastic releases toxic smoke; sorting allows recycling.', 2);

